let BUCKETS = null

function build() {
  if (BUCKETS) return BUCKETS
  const m = new Map()
  const groups = BUCKETED.split(SEP_GROUP)
  for (let g = 0; g < groups.length; g++) {
    const group = groups[g]
    const cut = group.indexOf(SEP_WORD)
    if (cut < 0) continue
    const head = group.slice(0, cut)
    const tails = group.slice(cut + 1).split(SEP_WORD)
    m.set(head, tails)
  }
  BUCKETS = m
  return m
}

export function normalize(s) {
  return String(s == null ? '' : s)
    .replace(/[\uFF01-\uFF5E]/g, (ch) => String.fromCharCode(ch.charCodeAt(0) - 0xfee0))
    .replace(/\s+/g, '')
    .toLowerCase()
}

export function hitWords(text) {
  const raw = String(text == null ? '' : text)
  if (!raw) return []
  const map = build()
  const variants = [raw.toLowerCase(), normalize(raw)]
  for (let vi = 0; vi < variants.length; vi++) {
    const v = variants[vi]
    if (v.length < 2) continue
    const found = []
    for (let i = 0; i < v.length - 1; i++) {
      const tails = map.get(v.slice(i, i + DEPTH_))
      if (!tails) continue
      for (let k = 0; k < tails.length; k++) {
        const seg = v.slice(i, i + DEPTH_) + tails[k]
        if (allowed(seg)) continue
        if (v.startsWith(seg, i) && found.indexOf(seg) < 0) {
          found.push(seg)
          if (found.length >= 3) return found
        }
      }
    }
    if (found.length) return found
  }
  return []
}

export function hasSensitive(text) {
  return hitWords(text).length > 0
}

export const LEXICON_TOTAL = 50837
const DEPTH_ = 2
